int cmonDoSomething(int value)
{
    std::string t = "";
    for (size_t i = 0; i < 1000 * value; i++, t += "a")
    {
        std::cerr << t << std::endl;
    }
    return t.size();
}

int cmonDoSomething()
{
    return cmonDoSomething(100);
}

